// Turn the base64 attachment into a real binary the Gmail node can attach.
const att = ($json.attachments ?? [])[0];
if (!att) throw new Error('No attachment on the request');

const binary = await this.helpers.prepareBinaryData(
  Buffer.from(att.contentBase64, 'base64'),
  att.filename,
  att.contentType,
);

return {
  json: {
    to: ($json.to ?? []).join(', '),
    cc: ($json.cc ?? []).join(', '),
    subject: $json.subject,
    html: $json.html,
    text: $json.text,
    filename: att.filename,
  },
  binary: { attachment: binary },
};
